package com.gathin.tvhome;
import android.app.*;
import android.content.*;
import android.media.AudioManager;
import android.view.*;
import android.widget.*;
import java.util.*;
/** Explicit local media-volume presets through an already enabled helper. No secure-setting grant. */
final class VolumePresets {
    static VolumePresetPolicy read(Context c){try{return new VolumePresetPolicy(ProfileSetup.global(c).getString(VolumePresetPolicy.KEY,""));}catch(RuntimeException bad){return new VolumePresetPolicy("");}}
    static String label(Context c){int n=0;for(int value:read(c).values)if(value>=0)n++;return n==0?"Off":n+" colour buttons · this TV";}
    static boolean handle(Context c,KeyEvent e){if(e.getKeyCode()<183||e.getKeyCode()>186||e.isFromSource(InputDevice.SOURCE_GAMEPAD)||e.isFromSource(InputDevice.SOURCE_JOYSTICK))return false;int percent=read(c).percent(e.getKeyCode());if(percent<0)return false;AudioManager audio=c.getSystemService(AudioManager.class);if(audio==null||audio.isVolumeFixed())return false;if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){try{int min=android.os.Build.VERSION.SDK_INT>=28?audio.getStreamMinVolume(AudioManager.STREAM_MUSIC):0;audio.setStreamVolume(AudioManager.STREAM_MUSIC,VolumePresetPolicy.level(percent,min,audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC)),AudioManager.FLAG_SHOW_UI);}catch(RuntimeException denied){return false;}}return true;}
    static void show(Activity a){if(!LauncherLock.require(a,()->show(a)))return;String before=ProfileSetup.global(a).getString(VolumePresetPolicy.KEY,"");int[] draft=read(a).values.clone();LinearLayout body=FreedomUi.body(a);body.addView(FreedomUi.text(a,"This TV · all profiles. Uses only the four colour buttons through an already enabled key helper. It never enables a service. Fixed-volume HDMI/CEC outputs may not support presets. Existing arrow, Input, power and held-volume behaviour stays available.",17));String[] names={"Red","Green","Yellow","Blue"};for(int i=0;i<4;i++){final int n=i;TextView button=FreedomUi.action(a,body,names[i]+" · "+(draft[i]<0?"Off":draft[i]+"%"),()->{});button.setOnClickListener(v->{EditText value=new EditText(a);value.setSingleLine(true);value.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);if(draft[n]>=0)value.setText(String.valueOf(draft[n]));AlertDialog dialog=new AlertDialog.Builder(a).setTitle(names[n]+" volume preset").setMessage("Media volume 0–100%. This does not run until you press the colour button.").setView(value).setNegativeButton("Cancel",null).setNeutralButton("Off",(d,w)->{draft[n]=-1;button.setText(names[n]+" · Off");}).setPositiveButton("Use in draft",null).create();dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(x->{try{int p=Integer.parseInt(value.getText().toString());if(p<0||p>100)throw new NumberFormatException();draft[n]=p;button.setText(names[n]+" · "+p+"%");dialog.dismiss();}catch(NumberFormatException invalid){value.setError("Use 0–100");}}));dialog.show();});}AlertDialog[] dialog={null};FreedomUi.action(a,body,"Apply presets",()->{if(!LauncherLock.open(a)||!before.equals(ProfileSetup.global(a).getString(VolumePresetPolicy.KEY,""))){Toast.makeText(a,"Approval or presets changed. Open this page again.",Toast.LENGTH_LONG).show();return;}if(ProfileSetup.global(a).edit().putString(VolumePresetPolicy.KEY,VolumePresetPolicy.encode(draft)).commit()){dialog[0].dismiss();a.recreate();}});dialog[0]=FreedomUi.sheet(a,"Colour-button volume presets",body);}
    private VolumePresets(){}
}
